import { beforeAll, describe, expect, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'

describe('api tokens', () => {
  let http: TestApp

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  it('rejects an unauthenticated API request', async () => {
    const res = await app.request('/api/posts', { headers: { Accept: 'application/json' } })
    expect(res.status).toBe(401)
    const bad = await app.request('/api/posts', {
      headers: { Accept: 'application/json', Authorization: 'Bearer nope|nope' },
    })
    expect(bad.status).toBe(401)
    expect(http).toBeDefined()
  })
})
